import React, { useEffect, useState, useContext } from 'react';
import axios from 'axios';
import { useNavigate } from 'react-router-dom';
import AuthContext from '../context/AuthContext';

function Jobs() {
  const [jobs, setJobs] = useState([]);
  const [loading, setLoading] = useState(true);
  const navigate = useNavigate();
  const { user } = useContext(AuthContext);

  useEffect(() => {
    fetchJobs();
  }, []);

  const fetchJobs = async () => {
    try {
      const res = await axios.get('http://localhost:5001/api/jobs', { withCredentials: true });
      setJobs(res.data.data);
    } catch (err) {
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  const handleApply = (jobId) => {
    navigate(`/upload?jobId=${jobId}`);
  };

  return (
    <div className="page mt-10">
      <div className="container">
        <div className="flex justify-between items-center mb-6">
          <h2 className="text-2xl">Available Jobs</h2>
          {user && (user.role === 'recruiter' || user.role === 'admin') && (
            <button className="btn btn-primary" onClick={() => navigate('/create-job')}>
              Post New Job
            </button>
          )}
        </div>

        {loading ? (
          <div className="text-center py-10">
            <p className="muted">Loading opportunities...</p>
          </div>
        ) : (
          <div className="grid">
            {jobs.length === 0 ? (
              <div className="card text-center py-10">
                <p className="muted">No active job postings at the moment.</p>
              </div>
            ) : jobs.map(job => (
              <div className="card" key={job._id}>
                <h5 className="card-title">{job.title}</h5>
                <p className="card-text">{job.description}</p>
                <div className="mb-4">
                  <strong className="block text-sm mb-2">Required Skills:</strong>
                  <div className="flex flex-wrap">
                    {job.requiredSkills.map((skill, i) => (
                      <span key={i} className="badge bg-secondary">{skill}</span>
                    ))}
                  </div>
                </div>

                <div className="flex flex-col gap-2">
                  <button className="btn btn-primary w-full" onClick={() => handleApply(job._id)}>
                    Apply Now
                  </button>

                  {user && (user.role === 'recruiter' || user.role === 'admin') && (
                    <button className="btn btn-ghost w-full" onClick={() => navigate(`/history?jobId=${job._id}`)}>
                      View Applicants
                    </button>
                  )}
                </div>

                <div className="card-footer mt-4 muted text-sm">
                  Posted on {new Date(job.createdAt).toLocaleDateString()}
                </div>
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
}

export default Jobs;
